<h3>Go</h3>
{{ds:component/code-block|filename=main.go|language=go|code=package main\\n\\nimport (\\n\\t"context"\\n\\t"log"\\n\\t"os"\\n\\n\\t"github.com/godzilla-io/godzilla-go"\\n)\\n\\nfunc main() &#123;\\n\\tclient := godzilla.NewClient(os.Getenv("GODZILLA_API_KEY"))\\n\\n\\tsourceConnector, err := client.Connectors.Create(context.Background(), &godzilla.CreateConnectorRequest&#123;\\n\\t\\tType:      "postgres",\\n\\t\\tDirection: "source",\\n\\t\\tConfig: map[string]interface&#123;&#125;&#123;\\n\\t\\t\\t"connection_string": "postgres://...",\\n\\t\\t&#125;,\\n\\t&#125;)\\n\\tif err != nil &#123;\\n\\t\\tlog.Fatalf("Failed to create source connector: %v", err)\\n\\t&#125;\\n\\n\\tlog.Printf("Created source connector: %s\\\\n", sourceConnector.ID)\\n&#125;}}

